-- Curated real-product snapshot. Run after schema.sql.
-- Product pages, images and reference prices were verified on 2026-09-11.
on conflict (id) do update set
  sku=excluded.sku, category=excluded.category, name=excluded.name, store=excluded.store,
  price=excluded.price, match=excluded.match, size=excluded.size, url=excluded.url,
  image_url=excluded.image_url, styles=excluded.styles, tags=excluded.tags, verified_at=excluded.verified_at;
